@ Module preamble shared by every test module.  The property word comes from
@ the build, as TEST_MODULE_PROPERTIES, so one source serves the protected and
@ the privileged modules; everything else is the layout the Cortex-M module
@ ports document.  Every module names its start function module_start.

#ifndef TEST_MODULE_PROPERTIES
#error "TEST_MODULE_PROPERTIES must be defined by the build"
#endif

    .syntax unified
    .section .preamble, "ax"
    .align  4

    .global __txm_module_preamble
    .global module_start
    .global _txm_module_thread_shell_entry
    .global _txm_module_callback_request_thread_entry

__txm_module_preamble:
    .dc.l   0x4D4F4455                                          @ Module ID
    .dc.l   0x6                                                 @ Module major version
    .dc.l   0x1                                                 @ Module minor version
    .dc.l   32                                                  @ Preamble size in 32-bit words
    .dc.l   0x7E57C0DE                                          @ Application-defined module ID
    .dc.l   TEST_MODULE_PROPERTIES                              @ Properties: GNU, and the test's mode
    .dc.l   _txm_module_thread_shell_entry - . - 0              @ Shell entry
    .dc.l   module_start - . - 0                                @ Start thread entry
    .dc.l   0                                                   @ Stop thread entry, none
    .dc.l   1                                                   @ Start/stop thread priority
    .dc.l   1024                                                @ Start/stop thread stack size
    .dc.l   _txm_module_callback_request_thread_entry - . - 0   @ Callback thread entry
    .dc.l   1                                                   @ Callback thread priority
    .dc.l   1024                                                @ Callback thread stack size
    .dc.l   __code_size__                                       @ Code size, from the link
    .dc.l   __data_size__                                       @ Data size, from the link
    .rept   16
    .dc.l   0                                                   @ Reserved
    .endr
